class PredictionResult {
  final String breed;
  final double confidence;
  final String size;
  final String shape;
  final String color;
  final String coat;
  final String headFace;
  final String body;
  final Map<String, String> temperament;
  final String purpose;
  final String gender;
  final String age;
  final String weight;
  final Map<String, dynamic>? metadata;

  PredictionResult({
    required this.breed,
    required this.confidence,
    required this.size,
    required this.shape,
    required this.color,
    required this.coat,
    required this.headFace,
    required this.body,
    required this.temperament,
    required this.purpose,
    required this.gender,
    required this.age,
    required this.weight,
    this.metadata,
  });
}

