  Future<void> _initializeModel() async {
    _log('🚀 Initializing models...');
    try {
      // Load dog detector model (binary classification)
      _dogDetectorInterpreter = await Interpreter.fromAsset(
        'models/dog_detector.tflite',
      );
      _log('✅ Dog detector model loaded');

      // Load breed identification model
      await _loadModel();
      await _loadLabels();
      _isModelInitialized = true;
    } catch (e) {
      _log('❌ Failed to load dog detector model: $e', type: 'ERROR');
      // If dog detector model doesn't exist, we'll use fallback logic
      await _loadModel();
      await _loadLabels();
      _isModelInitialized = true;
    }
  }

  Future<void> _predictImage(File imageFile) async {
    setState(() {
      _loading = true;
      _error = '';
      _predictionResult = null;
      _isDogDetected = false;
      _image = imageFile;
    });

    // First check if image contains a dog
    final isDog = await _checkIfDog(imageFile);

    if (!isDog) {
      setState(() {
        _loading = false;
        _isDogDetected = false;
      });
      return;
    }

    // If dog is detected, proceed with breed prediction
    await _predictDogBreed(imageFile);
  }

  Future<bool> _checkIfDog(File image) async {
    try {
      if (_dogDetectorInterpreter == null) {
        _log('⚠️ Dog detector model not available, using fallback logic');
        // Fallback: check if image contains typical dog-like features
        return await _fallbackDogCheck(image);
      }

      final imageBytes = await image.readAsBytes();
      final decodedImage = img.decodeImage(imageBytes);
      if (decodedImage == null) throw Exception('Failed to decode image');

      // Preprocess image for dog detection
      TensorImage inputImage = TensorImage(TfLiteType.float32);
      inputImage.loadImage(decodedImage);

      final cropSize = decodedImage.width < decodedImage.height
          ? decodedImage.width
          : decodedImage.height;

      final imageProcessor = ImageProcessorBuilder()
          .add(ResizeWithCropOrPadOp(cropSize, cropSize))
          .add(ResizeOp(224, 224, ResizeMethod.BILINEAR))
          .add(NormalizeOp(0, 255))
          .build();

      inputImage = imageProcessor.process(inputImage);

      final outputBuffer = TensorBuffer.createFixedSize(
        _dogDetectorInterpreter!.getOutputTensor(0).shape,
        _dogDetectorInterpreter!.getOutputTensor(0).type,
      );

      _dogDetectorInterpreter!.run(inputImage.buffer, outputBuffer.buffer);
      final predictions = outputBuffer.getDoubleList();

      // Assuming binary classification: [not_dog_probability, dog_probability]
      final dogProbability = predictions.length > 1 ? predictions[1] : predictions[0];

      _log('🐕 Dog detection probability: ${(dogProbability * 100).toStringAsFixed(2)}%');

      // Threshold for dog detection (adjust as needed)
      return dogProbability > 0.7;

    } catch (e) {
      _log('❌ Dog detection error: $e', type: 'ERROR');
      // Fallback to basic check
      return await _fallbackDogCheck(image);
    }
  }

  Future<bool> _fallbackDogCheck(File image) async {
    try {
      // Basic fallback: if breed prediction confidence > 30%, assume it's a dog
      // This is not ideal but works as fallback
      final imageBytes = await image.readAsBytes();
      final decodedImage = img.decodeImage(imageBytes);
      if (decodedImage == null) return false;

      TensorImage inputImage = TensorImage(TfLiteType.float32);
      inputImage.loadImage(decodedImage);

      final cropSize = decodedImage.width < decodedImage.height
          ? decodedImage.width
          : decodedImage.height;

      final imageProcessor = ImageProcessorBuilder()
          .add(ResizeWithCropOrPadOp(cropSize, cropSize))
          .add(ResizeOp(224, 224, ResizeMethod.BILINEAR))
          .add(NormalizeOp(0, 255))
          .build();

      inputImage = imageProcessor.process(inputImage);

      final outputBuffer = TensorBuffer.createFixedSize(
        _interpreter!.getOutputTensor(0).shape,
        _interpreter!.getOutputTensor(0).type,
      );

      _interpreter!.run(inputImage.buffer, outputBuffer.buffer);
      final predictions = outputBuffer.getDoubleList();

      // Find max confidence
      double maxConfidence = 0.0;
      for (final prediction in predictions) {
        if (prediction > maxConfidence) {
          maxConfidence = prediction;
        }
      }

      _log('⚠️ Fallback dog check - max breed confidence: ${(maxConfidence * 100).toStringAsFixed(2)}%');

      // If any breed confidence > 30%, assume it's a dog
      return maxConfidence > 0.3;

    } catch (e) {
      _log('❌ Fallback dog check failed: $e', type: 'ERROR');
      return false;
    }
  }

  void _log(String message, {String type = 'INFO'}) {
    final timestamp = DateTime.now().toIso8601String();
    final logMessage = '[$timestamp] [$type] $message';
    debugPrint(logMessage);
  }

  Future<void> _loadModel() async {
    try {
      _log('📦 Loading TensorFlow Lite model...');
      _interpreter = await Interpreter.fromAsset(
        'models/dog_identifier.tflite',
      );

      final inputTensor = _interpreter!.getInputTensor(0);
      final outputTensor = _interpreter!.getOutputTensor(0);
      _log('✅ Breed model loaded successfully');
      _log('📊 Input shape: ${inputTensor.shape}');
      _log('📊 Output shape: ${outputTensor.shape}');
    } catch (e) {
      _log('❌ Failed to load breed model: $e', type: 'ERROR');
      setState(() {
        _error = 'Failed to load AI model: $e';
        _loading = false;
      });
    }
  }

  Future<void> _loadLabels() async {
    try {
      _log('📝 Loading breed labels...');
      final data = await rootBundle.loadString('assets/labels.txt');
      final allLabels = LineSplitter.split(
        data,
      ).map((e) => e.trim()).where((e) => e.isNotEmpty).toList();

      final uniqueLabels = <String>{};
      final filteredLabels = [
        for (final label in allLabels)
          if (uniqueLabels.add(label)) label,
      ];

      setState(() => _labels = filteredLabels);
      _log('✅ Labels loaded successfully! Total: ${filteredLabels.length}');
      _log('📋 Labels: ${filteredLabels.take(5).toList()}...');
    } catch (e) {
      _log('❌ Label load failed: $e', type: 'ERROR');
      setState(() {
        _labels = [
          'Affenpinscher',
          'Afghan Hound',
          'Airedale',
          'Akita',
          'American Bulldog',
          'Australian Shepherd',
          'Beagle',
          'Boxer',
          'Bulldog',
          'Chihuahua',
          'Endebucher Mountain Dog',
        ];
        _log('⚠️ Using default labels');
      });
    }
  }

  Future<void> _predictDogBreed(File image) async {
    if (_interpreter == null || _labels == null || _labels!.isEmpty) {
      setState(() {
        _loading = false;
        _error =
        'Offline model not available. Please check if model files are in place.';
      });
      return;
    }

    try {
      final imageBytes = await image.readAsBytes();
      final decodedImage = img.decodeImage(imageBytes);
      if (decodedImage == null) throw Exception('Failed to decode image');

      TensorImage inputImage = TensorImage(TfLiteType.float32);
      inputImage.loadImage(decodedImage);

      final cropSize = decodedImage.width < decodedImage.height
          ? decodedImage.width
          : decodedImage.height;

      final imageProcessor = ImageProcessorBuilder()
          .add(ResizeWithCropOrPadOp(cropSize, cropSize))
          .add(ResizeOp(224, 224, ResizeMethod.BILINEAR))
          .add(NormalizeOp(0, 255))
          .build();

      inputImage = imageProcessor.process(inputImage);
      final outputTensor = _interpreter!.getOutputTensor(0);
      final outputBuffer = TensorBuffer.createFixedSize(
        outputTensor.shape,
        outputTensor.type,
      );

      _interpreter!.run(inputImage.buffer, outputBuffer.buffer);
      final predictions = outputBuffer.getDoubleList();

      double maxConfidence = 0.0;
      int maxIndex = 0;

      for (int i = 0; i < predictions.length; i++) {
        if (predictions[i] > maxConfidence) {
          maxConfidence = predictions[i];
          maxIndex = i;
        }
      }

      if (maxIndex >= _labels!.length) {
        throw Exception('Prediction index out of bounds');
      }

      final predictedBreed = _labels![maxIndex];
      final confidence = maxConfidence;

      _log(
        '🎯 Prediction: $predictedBreed with confidence: ${(confidence * 100).toStringAsFixed(2)}%',
      );

      // Check if confidence is too low
      if (confidence < 0.2) {
        _log('❌ Confidence too low (${(confidence * 100).toStringAsFixed(1)}%) - possibly not a dog');
        setState(() {
          _loading = false;
          _isDogDetected = false;
        });
        return;
      }

      final breedInfo = _getBreedInfo(predictedBreed);

      setState(() {
        _predictionResult = PredictionResult(
          breed: predictedBreed,
          confidence: confidence,
          size: breedInfo['size'] ?? "Medium",
          shape: breedInfo['shape'] ?? "Well Proportioned",
          color: breedInfo['color'] ?? "Various",
          coat: breedInfo['coat'] ?? "Double Coat",
          headFace: breedInfo['headFace'] ?? "Breed-Specific",
          body: breedInfo['body'] ?? "Balanced",
          temperament: breedInfo['temperament'] != null
              ? Map<String, String>.from(breedInfo['temperament'])
              : {
            "Energy Level": "Moderate",
            "Trainability": "Moderate",
            "Social Behavior": "Friendly",
            "Family Compatibility": "Good",
            "Child Friendliness": "Good",
          },
          purpose: breedInfo['purpose'] ?? "Companion",
          gender: "Unknown",
          age: "Adult",
          weight: breedInfo['weight'] ?? "Varies by Breed",
        );
        _loading = false;
        _isDogDetected = true;
      });
    } catch (e) {
      _log('❌ Breed prediction error: $e', type: 'ERROR');
      setState(() {
        _loading = false;
        _isDogDetected = false;
        _error = 'Failed to analyze image: $e';
      });
    }
  }
