          },
          'purpose': 'Companion',
          'weight': 'Varies by breed',
        };
  }


  String _formatBreedName(String name) {
    return name
        .replaceAll('-', ' ')
        .split(' ')
        .map((word) => word[0].toUpperCase() + word.substring(1))
        .join(' ');
  }

  Widget _buildResultsSection() {
    if (_predictionResult == null) return const SizedBox();

    final result = _predictionResult!;

    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Container(
          height: 245.h,
          width: double.infinity,
          margin: EdgeInsets.only(bottom: 20.h),
          decoration: BoxDecoration(
            borderRadius: BorderRadius.circular(12),
            image: DecorationImage(
              image: FileImage(_image!),
              fit: BoxFit.cover,
            ),
          ),
        ),

        Row(
          mainAxisAlignment: MainAxisAlignment.spaceBetween,
          children: [
            Expanded(
              child: Text(
                _formatBreedName(result.breed),
                style: TextStyle(
                  fontSize: 24.sp,
                  fontWeight: FontWeight.bold,
                  color: const Color(0xFF101010),
                ),
                maxLines: 2,
                overflow: TextOverflow.ellipsis,
              ),
            ),

            Container(
              width: 103.w,
              height: 103.h,
              decoration: BoxDecoration(
                shape: BoxShape.circle,
                color: const Color(0xFF7DFAC4).withOpacity(0.24),
              ),
              child: Center(
                child: Column(
                  mainAxisAlignment: MainAxisAlignment.center,
                  children: [
                    Text(
                      "${(result.confidence * 100).toStringAsFixed(0)}%",
                      style: TextStyle(
                        fontSize: 30.sp,
                        fontWeight: FontWeight.bold,
                        color: const Color(0xFF05E51F),
                      ),
                    ),
                    SizedBox(height: 4.h),
                    Text(
                      "Confidence",
                      style: TextStyle(
                        fontSize: 12.sp,
                        color: Colors.grey[600],
                      ),
                    ),
                  ],
                ),
              ),
            ),
          ],
        ),
        SizedBox(height: 24.h),

        GridView.count(
          shrinkWrap: true,
          physics: const NeverScrollableScrollPhysics(),
          crossAxisCount: 2,
          crossAxisSpacing: 12.w,
          mainAxisSpacing: 12.h,
          childAspectRatio: 2.5,
          children: [
            _buildCharacteristicCard(
              iconPath: "assets/images/size.svg",
              title: "Size",
              value: result.size,
            ),
            _buildCharacteristicCard(
              iconPath: "assets/images/shape.svg",
              title: "Shape",
              value: result.shape,
            ),
            _buildCharacteristicCard(
              iconPath: "assets/images/regular.svg",
              title: "Color",
              value: result.color,
            ),
            _buildCharacteristicCard(
              iconPath: "assets/images/coat.svg",
              title: "Coat",
              value: result.coat,
            ),
            _buildCharacteristicCard(
              iconPath: "assets/images/flex_dog.svg",
              title: "Head & Face",
              value: result.headFace,
            ),
            _buildCharacteristicCard(
              iconPath: "assets/images/akar.svg",
              title: "Purpose",
              value: result.purpose,
            ),
            _buildCharacteristicCard(
              iconPath: "assets/images/fluent.svg",
              title: "Body",
              value: result.body,
            ),
            _buildCharacteristicCard(
              iconPath: "assets/images/akar.svg",
              title: "Weight",
              value: result.weight,
            ),
          ],
        ),
        SizedBox(height: 24.h),

        Text(
          "Temperament & Characteristics",
          style: TextStyle(
            fontSize: 18.sp,
            fontWeight: FontWeight.bold,
            color: const Color(0xFF820DFF),
          ),
        ),
        SizedBox(height: 16.h),

        Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            _buildTemperamentCard(
              "Energy Level",
              result.temperament["Energy Level"] ?? "Moderate",
            ),
            SizedBox(height: 12.h),
            _buildTemperamentCard(
              "Trainability",
              result.temperament["Trainability"] ?? "Moderate",
            ),
            SizedBox(height: 12.h),
            _buildTemperamentCard(
              "Social Behavior",
              result.temperament["Social Behavior"] ?? "Friendly",
            ),
            SizedBox(height: 12.h),
            _buildTemperamentCard(
              "Family Compatibility",
              result.temperament["Family Compatibility"] ?? "Good",
            ),
            SizedBox(height: 12.h),
            _buildTemperamentCard(
              "Child Friendliness",
              result.temperament["Child Friendliness"] ?? "Good",
            ),
          ],
        ), SizedBox(height: 16.h),
        Row(
          mainAxisAlignment: MainAxisAlignment.spaceBetween,
          children: [
            Expanded(
              child: RoundButton(
                title: "Cancel",
                height: 38.h,
                width: 39.w,
                borderRadius: 47.r,
                textColors: const Color(0xFFFF0505),
                backgroundColors: const Color(0xFFFFE5E5),
                isSelected: true,
                onPress: () {
                  Navigator.pop(context);
                },
              ),
            ),
            SizedBox(width: 12.w),
            Expanded(
              child: RoundButton(
                title: "Save Results",
                height: 45.h,
                width: 163.w,
                borderRadius: 47.r,
                textColors: const Color(0xFFFFFFFF),
                backgroundColors: const Color(0xFF2A2A2A),
                isSelected: true,
                onPress: () {
                  if (_predictionResult != null) {
                    // Prepare the data
                    final resultData = {
                      'image': widget.imageFile,
                      'breedName': _predictionResult!.breed,
                      'confidence': _predictionResult!.confidence,
                      'formattedBreedName': _formatBreedName(
                        _predictionResult!.breed,
                      ),
                      'timestamp': DateTime.now(),
                    };

                    if (kDebugMode) {
                      print('💾 SAVING RESULT:');
                    }
                    if (kDebugMode) {
                      print('   Breed: ${resultData['breedName']}');
                    }
                    if (kDebugMode) {
                      print('   Confidence: ${resultData['confidence']}');
                    }
                    if (kDebugMode) {
                      print('   Image: ${widget.imageFile.path}');
                    }

                    // Get the provider and add scan
                    final scanProvider = Provider.of<ScanProvider>(
                      context,
                      listen: false,
                    );
                    scanProvider.addScan(resultData);

                    // Navigate back to HomeView
                    Navigator.pushNamed(context, RoutesName.dashboard);
                  }
                },
              ),
            ),
          ],
        ),
      ],
    );
  }
}





 



